function softCap(value: number, cls: StatClass, row: SoftCapRow): number {
  const [threshold, rate] = SOFT_CAPS[cls][row]
  if (threshold > 0 && value > threshold) {
    return threshold + rate * (value - threshold)
  }
  return value
}

